# ======================================================================
# exceptions.py
# ======================================================================

"""Exceptions.

These are part of the public surface precisely because the package's value is
in what it *refuses* to answer. ``ScopeRequired`` is raised when a caller asks
for a scoped fact without supplying the scope; the other two are raised by the
runtime guards, which are importable from production code, not just tests.
"""


__all__ = [
    "GeospatialSpecError",
    "ScopeRequired",
    "BaselineMismatch",
    "NodataUndeclared",
    "UnknownScope",
]


class GeospatialSpecError(Exception):
    """Base class for every error this package raises."""


class ScopeRequired(GeospatialSpecError, TypeError):
    """A scoped fact was requested without the scope that determines it.

    Subclasses :class:`TypeError` because that is what a caller who wrote
    ``boa_offset()`` expects to catch, and because the mistake is genuinely a
    call-signature error.
    """


class BaselineMismatch(GeospatialSpecError):
    """Data's declared processing baseline contradicts what the code assumes.

    Raised by :func:`geospatial_spec.sentinel2.assert_baseline_consistent`.
    The message names the offset the calling code's thresholds are wrong by,
    because "mismatch" alone does not tell a maintainer what to change.
    """


class NodataUndeclared(GeospatialSpecError):
    """A resampling or read profile omits the nodata declaration it needs.

    Raised by :func:`geospatial_spec.sentinel2.assert_nodata_declared`. The
    live bug this exists for: bilinear resampling with neither ``src_nodata``
    nor ``dst_nodata`` set smears a nodata region into its valid neighbours,
    silently and in-bounds.
    """


class UnknownScope(GeospatialSpecError, ValueError):
    """The scope supplied is syntactically valid but not one this table knows."""

# ======================================================================
# _types.py
# ======================================================================

"""Introspection types.

``SpecFact`` is deliberately *not* how facts are read. It is what
:func:`geospatial_spec.explain` returns — a description of a fact, carrying its
citation and the witness line that corroborates it, for tooling and error
messages.

The distinction is the product. A fact you can read as ``FACTS[0].value`` is a
bare constant wearing a dataclass, and a call site can dereference it without
answering the question the guard exists to force ("does my data carry the
offset?"). So ``SpecFact`` is a *return value*, never a module-level constant,
and it is never the path by which a caller obtains a number to compute with.
"""




@dataclass(frozen=True)
class SpecFact:
    """A fact, its authority, and the witness that corroborates it.

    Returned by :func:`geospatial_spec.explain`. The ``value`` field is present
    because an explanation without the value is useless to a human reading an
    error message — but reaching it requires having already called ``explain``
    with the scope that identifies *which* fact applies, which is the same
    question the guard functions force. It is an explanation, not an accessor.
    """

    name: str
    value: Any
    cite: str
    scope: str
    witness: str | None = None
    notes: tuple[str, ...] = field(default_factory=tuple)

    def __str__(self) -> str:
        parts = [f"{self.name} = {self.value!r}", f"  scope: {self.scope}", f"  cite:  {self.cite}"]
        if self.witness:
            parts.append(f"  witness: {self.witness}")
        parts.extend(f"  note:  {n}" for n in self.notes)
        return "\n".join(parts)

# ======================================================================
# _witness.py
# ======================================================================

"""The witness protocol.

Every fact in this package carries two independent authorities: a specification
citation (a human-readable pointer to the document) and a *witness* — a real
artifact that declares the same value, machine-checked in CI. A fact with only
a citation is one person's reading of a PDF, which is the defect this project
is named after.

A witness is any callable returning ``dict[str, object]``: a mapping from fact
name to the value the artifact declares. Nothing here is ESA-specific. A team
can check their own constants against their DB schema, an OpenAPI document, or
a spec JSON, which is what makes this a tool rather than a lookup table.
"""



WitnessFn = Callable[[], "dict[str, object]"]


class Witness(Protocol):
    """Anything that can state what an external artifact declares."""

    def __call__(self) -> dict[str, object]: ...


def from_json(path: str | Path, *, key: str | None = None) -> WitnessFn:
    """Witness backed by a JSON document.

    ``key`` optionally selects a nested object to use as the fact mapping.
    """

    def _read() -> dict[str, object]:
        data = json.loads(Path(path).read_text())
        if key is not None:
            data = data[key]
        if not isinstance(data, dict):
            raise TypeError(f"witness {path} did not yield an object")
        return data

    return _read


ExtractFn = Callable[[ElementTree.Element], "dict[str, object]"]


def text(element: ElementTree.Element | None, path: str | None = None) -> str:
    """Required text content of an element, or a clear error naming what is absent.

    Shared by every XML-backed witness. A witness missing a field it is supposed
    to corroborate is a broken witness, and it must say so loudly rather than
    letting ``None`` slide into the fact table where it would compare unequal to
    everything and produce a confusing failure far from the cause.
    """
    if path is None:
        target = element
    else:
        target = element.find(path) if element is not None else None
    if target is None or target.text is None:
        raise ValueError(f"witness is missing required element {path or '(self)'}")
    return target.text.strip()


def from_xml(path: str | Path, extract: ExtractFn) -> WitnessFn:
    """Witness backed by an XML document and an extraction function.

    The extraction function receives the parsed root element and returns the
    fact mapping. This is the form the Sentinel witnesses use, because product
    metadata is XML and the interesting values are scattered across it.
    """

    def _read() -> dict[str, object]:
        root = ElementTree.parse(Path(path)).getroot()
        return extract(root)

    return _read


def from_mapping(mapping: dict[str, object]) -> WitnessFn:
    """Witness from an in-memory mapping.

    For facts whose authority is a document that cannot be vendored (a paywalled
    standard, a value only stated in prose). Weaker than the others by design:
    it records a transcription rather than checking one, so it is used sparingly
    and the citation carries the weight.
    """

    def _read() -> dict[str, object]:
        return dict(mapping)

    return _read


# Bind the helpers onto the stand-in namespace, so `witness.text(...)` in the
# fact-extraction functions resolves exactly as it does in the package.
witness.text = text
from_json = from_json
witness.from_xml = from_xml
witness.from_mapping = from_mapping


# ======================================================================
# _table.py
# ======================================================================

"""The fact registry.

Values live here, private, keyed by name. Public modules expose *callables* that
consult this table after the caller has supplied the scope that determines which
value applies. Nothing in the public surface hands back a number without first
being told the context that makes the number correct.

``FactTable`` is also the extensibility surface (§1.4): a team registers their
own facts with their own citations and witnesses, and gets the same guard
discipline for their own domain.
"""




F = TypeVar("F", bound=Callable[..., Any])
T = TypeVar("T")


@dataclass(frozen=True)
class _Entry:
    name: str
    value: Any
    cite: str
    scope: str
    witness: WitnessFn | None
    witness_key: str | None
    notes: tuple[str, ...]


class FactTable:
    """A named collection of spec facts, their citations, and their witnesses.

    Registration records a value; it does not expose one. The only way a caller
    reads a value is through a guard function that requires the scope.
    """

    def __init__(self, name: str) -> None:
        self.name = name
        self._entries: dict[str, _Entry] = {}

    def register(
        self,
        name: str,
        value: Any,
        *,
        cite: str,
        scope: str,
        witness: WitnessFn | None = None,
        witness_key: str | None = None,
        notes: tuple[str, ...] = (),
    ) -> None:
        """Record a fact. ``witness_key`` defaults to ``name``."""
        if name in self._entries:
            raise ValueError(f"fact {name!r} is already registered in {self.name!r}")
        self._entries[name] = _Entry(
            name=name,
            value=value,
            cite=cite,
            scope=scope,
            witness=witness,
            witness_key=witness_key if witness_key is not None else name,
            notes=notes,
        )

    def get(self, name: str) -> Any:
        """Read a registered value. Private by convention — guards call this."""
        try:
            return self._entries[name].value
        except KeyError:
            raise UnknownScope(f"{self.name!r} has no fact named {name!r}") from None

    def get_as(self, name: str, kind: type[T]) -> T:
        """Read a registered value, asserting its type.

        Guard functions declare concrete return types; this keeps that promise
        checkable instead of laundering every value through ``Any``.
        """
        value = self.get(name)
        if not isinstance(value, kind):
            raise TypeError(
                f"fact {name!r} is {type(value).__name__}, not {kind.__name__}"
            )
        return value

    def explain(self, name: str) -> SpecFact:
        """Return the citation, scope and witness line for *name*."""
        try:
            entry = self._entries[name]
        except KeyError:
            raise UnknownScope(f"{self.name!r} has no fact named {name!r}") from None
        witness_line = None
        if entry.witness is not None:
            declared = entry.witness()
            if entry.witness_key in declared:
                witness_line = f"{entry.witness_key} = {declared[entry.witness_key]!r}"
        return SpecFact(
            name=entry.name,
            value=entry.value,
            cite=entry.cite,
            scope=entry.scope,
            witness=witness_line,
            notes=entry.notes,
        )

    def names(self) -> tuple[str, ...]:
        return tuple(sorted(self._entries))

    def check_witnesses(self) -> list[str]:
        """Verify every witnessed fact against its artifact.

        Returns a list of human-readable disagreements; empty means every fact
        that claims a witness is corroborated by it. This is what the fidelity
        test drives, and it is the reason the guard is not circular.
        """
        problems: list[str] = []
        for entry in self._entries.values():
            if entry.witness is None:
                continue
            declared = entry.witness()
            if entry.witness_key not in declared:
                problems.append(
                    f"{entry.name}: witness does not declare {entry.witness_key!r}"
                )
                continue
            if declared[entry.witness_key] != entry.value:
                problems.append(
                    f"{entry.name}: table says {entry.value!r}, "
                    f"witness says {declared[entry.witness_key]!r}"
                )
        return problems

    def unwitnessed(self) -> tuple[str, ...]:
        """Facts with no witness. Every one is a liability; keep the list short."""
        return tuple(
            sorted(n for n, e in self._entries.items() if e.witness is None)
        )

    def guard(
        self, *, cite: str, scope: str, witness: WitnessFn | None = None
    ) -> Callable[[F], F]:
        """Decorator registering a guard function's metadata (§1.4).

        The decorated function keeps its own body; this attaches the citation so
        ``explain`` and error messages can reach it, and so a team's own guards
        participate in the same witness checking.
        """

        def _decorate(fn: F) -> F:
            self.register(
                fn.__name__,
                value=None,
                cite=cite,
                scope=scope,
                witness=witness,
            )
            fn.__geospatial_spec_cite__ = cite  # type: ignore[attr-defined]
            fn.__geospatial_spec_scope__ = scope  # type: ignore[attr-defined]
            return fn

        return _decorate

